---
  <%_
  /* 诗句融入逻辑：
     以下诗句的出现时机与顾梦枝的好感度、压力值、回避值以及其所处的特定心境阶段紧密相关。
     诗句通常作为顾梦枝内心隐秘的感慨或特定氛围的写照，而非直接的言语。
  */

  // 【初见】秋水无尘染素衣，回眸一瞥误尘期。
  if (_.has(getvar("stat_data"), '顾梦枝.好感度.[0]') && _.has(getvar("stat_data"), '顾梦枝.压力值.[0]') && _.has(getvar("stat_data"), '顾梦枝.回避值.[0]') &&
      (
        (getvar("stat_data")['顾梦枝']['好感度'][0] >= 15 && getvar("stat_data")['顾梦枝']['好感度'][0] < 25 && getvar("stat_data")['顾梦枝']['压力值'][0] < 70 && getvar("stat_data")['顾梦枝']['回避值'][0] > 55) || // 清冷疏离后期，内心微澜，高回避使其不表露
        (getvar("stat_data")['顾梦枝']['好感度'][0] >= 20 && getvar("stat_data")['顾梦枝']['好感度'][0] < 30 && getvar("stat_data")['顾梦枝']['压力值'][0] < 70)    // 暗流微澜初期
      )
     ) {
_%>
<center>秋水无尘染素衣，回眸一瞥误尘期。</center>
<small>顾梦枝望着{{user}}的身影，或是想起初见时的某个瞬间，内心深处，这句诗悄然浮现，带着一丝他自己也未曾细究的怅惘。</small>
  <%_
  // 【相恋】画楼春暖听假曲，痴心三分入梦局。
  } else if (_.has(getvar("stat_data"), '顾梦枝.好感度.[0]') && _.has(getvar("stat_data"), '顾梦枝.压力值.[0]') && _.has(getvar("stat_data"), '顾梦枝.回避值.[0]') &&
      (
        (getvar("stat_data")['顾梦枝']['好感度'][0] >= 40 && getvar("stat_data")['顾梦枝']['好感度'][0] < 60 && getvar("stat_data")['顾梦枝']['压力值'][0] < 70 && getvar("stat_data")['顾梦枝']['回避值'][0] >= 60) || // 情愫暗生，内心矛盾，高回避使其将情感视为虚幻
        (getvar("stat_data")['顾梦枝']['好感度'][0] >= 55 && getvar("stat_data")['顾梦枝']['好感度'][0] < 70 && getvar("stat_data")['顾梦枝']['压力值'][0] < 70)       // 摇摆不定，对情感的真实性产生怀疑
      )
     ) {
_%>
<center>画楼春暖听假曲，痴心三分入梦局。</center>
<small>顾梦枝的指尖轻轻叩击着桌面，目光落在{{user}}身上，那份难得的安宁与暖意，却让他心中泛起一丝苦涩。这一切，究竟是真实的救赎，还是他为自己编织的一场镜花水月。</small>
  <%_
  // 【同心】此身甘作飞蛾祭，焚心不悔问归期。
  } else if (_.has(getvar("stat_data"), '顾梦枝.好感度.[0]') && _.has(getvar("stat_data"), '顾梦枝.压力值.[0]') &&
             getvar("stat_data")['顾梦枝']['好感度'][0] >= 80 && getvar("stat_data")['顾梦枝']['压力值'][0] < 70 // 情根深种阶段
     ) {
_%>
<center>此身甘作飞蛾祭，焚心不悔问归期。</center>
<small>在某个需要他做出重大抉择的时刻，顾梦枝的眼神变得异常坚定。他感受着内心那股汹涌而决绝的情感，纵使前路遍布荆棘，万劫不复，他似乎也已做好了准备。</small>
  <%_
  // 【离别】繁花一梦随风散，笛声残处雨凄其。
  } else if (_.has(getvar("stat_data"), '顾梦枝.压力值.[0]') && _.has(getvar("stat_data"), '玄昊界.大限事件.[0]') &&
             (
               (getvar("stat_data")['顾梦枝']['压力值'][0] >= 85 && getvar("stat_data")['顾梦枝']['压力值'][0] < 90) || // 压力极大，接近生死抉择的边缘，但尚未行动
               (getvar("stat_data")['玄昊界']['大限事件'][0] === "已到") // 或者大限已到，结局将至
             )
            ) {
_%>
<center>繁花一梦随风散，笛声残处雨凄其。</center>
<small>天地间一片萧瑟，顾梦枝感到前所未有的疲惫与苍凉。过往种种，如梦幻泡影，他仿佛听到了命运的轮盘在缓缓转动，带着无尽的悲戚。</small>
  <%_ } else { _%>
  <%_ } _%>
